class BookMyShow { int n,m,first=0;vector<int> remaining,maximum;vector<long long> sum;void build(int node,int left,int right){if(left==right){maximum[node]=m;sum[node]=m;return;}int middle=(left+right)/2;build(node*2,left,middle);build(node*2+1,middle+1,right);pull(node);}void pull(int node){maximum[node]=max(maximum[node*2],maximum[node*2+1]);sum[node]=sum[node*2]+sum[node*2+1];}void update(int node,int left,int right,int index){if(left==right){maximum[node]=remaining[index];sum[node]=remaining[index];return;}int middle=(left+right)/2;if(index<=middle)update(node*2,left,middle,index);else update(node*2+1,middle+1,right,index);pull(node);}int find(int node,int left,int right,int maxRow,int k){if(left>maxRow||maximum[node]<k)return -1;if(left==right)return left;int middle=(left+right)/2,result=find(node*2,left,middle,maxRow,k);return result>=0?result:find(node*2+1,middle+1,right,maxRow,k);}long long query(int node,int left,int right,int maxRow){if(left>maxRow)return 0;if(right<=maxRow)return sum[node];int middle=(left+right)/2;return query(node*2,left,middle,maxRow)+query(node*2+1,middle+1,right,maxRow);}public:BookMyShow(int n,int m):n(n),m(m),remaining(n,m),maximum(4*n),sum(4*n){build(1,0,n-1);}vector<int> gather(int k,int maxRow){int row=find(1,0,n-1,maxRow,k);if(row<0)return{};int start=m-remaining[row];remaining[row]-=k;update(1,0,n-1,row);return{row,start};}bool scatter(int k,int maxRow){if(query(1,0,n-1,maxRow)<k)return false;while(k){while(first<n&&!remaining[first])++first;int take=min(k,remaining[first]);remaining[first]-=take;k-=take;update(1,0,n-1,first);}return true;} };
